+  test("carries a symlink as a symlink, dangling or not", () => {
+    fileAt(join(workspace, "notes.md"), "agent notes\n");
+    fileAt(join(workspace, "real.md"), "the target\n");
+    symlinkSync("real.md", join(workspace, "link.md"));
