+      } finally {
+        chmodSync(workspace, 0o755);
+      }
+      expect(
+        snapshot(),
+        "an unreadable workspace would otherwise delete the snapshot the next run needs",
+      ).toContain("workspace/issue-7/notes.md");
+    },
+  );
+});
