405	/**
406	 * Replace `prefix` on the atomaton-data branch with the contents of `sourceDir`.
407	 *
408	 * Replace, not merge. A file the agent deleted has to be gone next run, or the
409	 * workspace becomes a place where deletions do not take -- the same silent shape
410	 * `unzip -o` produced for `.github/` before `self/` (see
411	 * `tests/contract/self-overlay.test.ts`). `git add --all <prefix>` after removing
412	 * the old tree stages the deletions along with the additions.
413	 *
414	 * The retry loop is `saveSession`'s, for the same reason: sibling agents on
415	 * decomposed issues push to this branch concurrently, and a rejected push means
416	 * someone else got there first rather than that anything is wrong.
417	 */
418	export function saveWorkspace(prefix: string, sourceDir: string, commitMessage: string): boolean {
419	  if (!existsSync(sourceDir)) return true;
420	  if (gitRun("ls-remote", "--exit-code", "origin", DATA_BRANCH).code !== 0) {
421	    // No branch yet means no session has ever been saved either. Leave creating it
422	    // to `saveSession`, which runs in the same job: a workspace with no session is
423	    // not a state worth bringing into existence.
424	    console.error(`[${DATA_BRANCH}] ${DATA_BRANCH} does not exist yet; skipping workspace save`);
425	    return false;
426	  }
427	
428	  gitRun("fetch", "origin", DATA_BRANCH);
429	  const worktreeDir = mkdtempSync(join(tmpdir(), "atomaton-data-ws-"));
430	  gitRun("worktree", "add", worktreeDir, `origin/${DATA_BRANCH}`);
431	
432	  let saved = false;
433	  try {
434	    gitIn(worktreeDir, "config", "user.email", "action@github.com");
435	    gitIn(worktreeDir, "config", "user.name", "GitHub Actions");
436	
437	    for (let attempt = 1; attempt <= 5; attempt++) {
438	      gitIn(worktreeDir, "fetch", "origin", DATA_BRANCH);
439	      gitIn(worktreeDir, "reset", "--hard", `origin/${DATA_BRANCH}`);
440	
441	      const target = join(worktreeDir, prefix);
442	      rmSync(target, { recursive: true, force: true });
443	      mkdirSync(dirname(target), { recursive: true });
444	      const skipped = copyWorkspace(sourceDir, target);
445	      if (skipped === undefined) {
446	        console.error(`[${DATA_BRANCH}] cannot read ${sourceDir}; leaving the previous workspace snapshot alone`);
447	        break;
448	      }
449	      // A warning annotation rather than a log line: the save itself succeeds, so
450	      // nothing else in the job says a file the agent left will not be there next run.
451	      for (const path of skipped) {
452	        console.error(
453	          `::warning::workspace snapshot: left ${path} out, because the user saving it cannot read it`,
454	        );
455	      }
456	      gitIn(worktreeDir, "add", "--all", prefix);
457	
458	      if (gitIn(worktreeDir, "diff", "--cached", "--quiet").code === 0) {
459	        saved = true;
460	        break;
461	      }
462	
463	      gitIn(worktreeDir, "commit", "-m", commitMessage);
464	
465	      if (gitIn(worktreeDir, "push", "origin", `HEAD:${DATA_BRANCH}`).code === 0) {
466	        saved = true;
467	        break;
468	      }
469	
470	      console.error(`[${DATA_BRANCH}] workspace push attempt ${attempt} failed (concurrent push) -- retrying`);
471	      Bun.sleepSync(attempt * 2000);
472	    }
473	  } finally {
474	    gitRun("worktree", "remove", "--force", worktreeDir);
475	    rmSync(worktreeDir, { recursive: true, force: true });
476	  }
477	
478	  return saved;
479	}

