1	/**
2	 * workspace-size.ts — when the scratch workspace has grown past what will be kept.
3	 *
4	 * ## Why this is checked during the run and not when the workspace is saved
5	 *
6	 * Saving happens after the agent has finished. A limit enforced there is correct and
7	 * useless: the run that wrote the 900 MB file is over, its `/tmp` is gone with the job,
8	 * and the next run restores the last version that *did* fit — so the agent that is told
9	 * has nothing to delete and did nothing wrong. The condition has to be reported while
10	 * the files still exist and the agent can still remove them.
11	 *
12	 * So this runs from an `after_tool` hook on every tool, and what it produces is a notice
13	 * appended to whatever result the agent was already reading. Every tool, because an
14	 * agent may write a large file through one server and then spend twenty calls in
15	 * another; a hook on the writing server alone would say nothing for those twenty.
16	 *
17	 * ## What the numbers are, and what they are not
18	 *
19	 * Measured over every issue this repository has run: the whole `workspace/` tree on
20	 * `atomaton-data` is **five files and 142 bytes**. The limits below are not tuned against
21	 * that distribution, because there is nothing there to tune against — they are set where
22	 * a legitimate use cannot reach and an accident lands immediately.
23	 *
24	 * ```text
25	 *   total       5 MB    ~37,000x the measured usage; one build artifact exceeds it
26	 *   one file    1 MB    separates "a big thing" from "many small things", which
27	 *                       have different causes and different fixes
28	 *   files        200    a copied node_modules trips this before it trips the bytes
29	 * ```
30	 *
31	 * The three exist separately because the notice has to say what to do, and "delete the
32	 * 900 MB bundle" and "you have copied a dependency tree in here" are different
33	 * sentences.
34	 */
35	
36	/** Everything the limits are compared against, and everything the notice quotes. */
37	export interface WorkspaceUsage {
38	  bytes: number;
39	  files: number;
40	  /** The largest files, biggest first, so the notice can name them. */
41	  largest: { path: string; bytes: number }[];
42	}
43	
44	/** Total size of the workspace, above which nothing in it is carried forward. */
45	export const MAX_TOTAL_BYTES = 5 * 1024 * 1024;
46	
47	/** Size of a single file, above which that file alone is the problem. */
48	export const MAX_FILE_BYTES = 1024 * 1024;
49	
50	/** How many files may be there, whatever they weigh. */
51	export const MAX_FILES = 200;
52	
53	/** How many of the largest files the notice names. Enough to act on, not a listing. */
54	const NAMED = 3;
55	
56	function readable(bytes: number): string {
57	  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
58	  if (bytes >= 1024) return `${Math.round(bytes / 1024)} KB`;
59	  return `${bytes} bytes`;
60	}
61	
62	/**
63	 * What to tell the agent, or nothing.
64	 *
65	 * Phrased as a consequence rather than as a rule: "nothing you put there will reach the
66	 * next run" is a fact about its work, where "the workspace exceeds its limit" is a fact
67	 * about our configuration. Measured elsewhere in this repository, a refusal that said
68	 * what to do instead was followed and one that only said no was not.
69	 */
70	export function overLimitNotice(usage: WorkspaceUsage, path: string): string | undefined {
71	  const reasons: string[] = [];
72	  if (usage.bytes > MAX_TOTAL_BYTES) {
73	    reasons.push(`it holds ${readable(usage.bytes)}, over the ${readable(MAX_TOTAL_BYTES)} limit`);
74	  }
75	  if (usage.files > MAX_FILES) {
76	    reasons.push(`it holds ${usage.files} files, over the limit of ${MAX_FILES}`);
77	  }
78	  const huge = usage.largest.filter((f) => f.bytes > MAX_FILE_BYTES);
79	  if (huge.length > 0) {
80	    const subject = huge.length === 1 ? "one file is" : `${huge.length} files are`;
81	    reasons.push(`${subject} over the ${readable(MAX_FILE_BYTES)} single-file limit`);
82	  }
83	  if (reasons.length === 0) return undefined;
84	
85	  const named = usage.largest
86	    .slice(0, NAMED)
87	    .map((f) => `  ${readable(f.bytes).padStart(9)}  ${f.path}`)
88	    .join("\n");
89	
90	  return [
91	    `--- ${path} is over its limit; this is not part of the answer above ---`,
92	    `Nothing you have put there will reach the next run on this issue: ${reasons.join(", and ")}.`,
93	    "",
94	    "The largest are:",
95	    named,
96	    "",
97	    `Delete what the next run does not need. ${path} is an ordinary directory, so the ` +
98	      "tools you already use remove a file there. Build output, dependency trees and logs do not " +
99	      "belong in it; notes, scratch scripts and intermediate results do. If what is there is only " +
100	      "useful to you now, leave it and let it go when this run ends.",
101	  ].join("\n");
102	}

